  agents_called: agentsCalled,
  tool_reason: cur.tool_reason,
  action: cur.action ?? null,
  model: usesModel ? cfg.agent_model : null,
  memory_setting: usesModel ? cfg.memory_setting : null,
  tokens_in: null,
  tokens_out: null,
  cost_usd: jev ? num(jev.jev_cost_usd) : null,
  cost_usd_listprice: null,
  duration_ms: Date.now() - cfg.start_time,
  status: cur.status
