// Wertet die Protokollzeilen der Sitzung aus: wie viele Nachrichten gab es schon, ist es die erste Antwort, ist die Obergrenze erreicht.
// Gezaehlt wird jede Protokollzeile der Sitzung (jeder Weg schreibt genau eine Zeile je Nachricht).
// Gefahr fuer Personen hat Vorrang vor der Obergrenze: Eine Nachricht mit einem Gefahrwort (Feuer, Brand, verletzt, Notfall, Unfall und aehnliche) geht
// auch ueber der Grenze weiter zu Jev und zum Agenten, damit die Eilmeldung ausgeloest wird, hoechstens fuer 5 Nachrichten ueber der Grenze
// (sonst liesse sich die Obergrenze mit einem Gefahrwort beliebig umgehen). Das ist eine Wortliste, keine Bedeutungserkennung.
// v11 (V6): frage_vorhanden ist false, wenn nach Abzug von Leerzeichen, Tabs, Zeilenumbruechen, Steuer- und Format-Zeichen (Unicode Cc, Cf), kombinierenden Zeichen (Mn),
// Variationsselektoren und den Fuellzeichen U+115F, U+1160, U+3164, U+FFA0, U+17B4, U+17B5, U+2800, U+034F, U+FFFC nichts uebrig bleibt. Das ist eine Zeichenliste, keine Garantie fuer jedes denkbare unsichtbare Zeichen.
// Die Weiche Frage vorhanden? liest nur dieses Feld. Eine leere Frage zaehlt als Nachricht der Sitzung (sie bekommt eine Protokollzeile mit route leer).
const cfg = $('Konfiguration [Edit Fields]').first().json;
const rows = $input.all().map(i => i.json).filter(r => Number(r.id ?? 0) > 0);
const bisher = rows.length;
const grenze = Number(cfg.max_nachrichten);
const puffer = 5;
const BUCH = 'A-Za-zÄÖÜäöüß';
const gefahrWort = new RegExp('(?<![' + BUCH + '])(feuer|brand|brennt|brennen|qualm|rauch|explosion|verletzt\\w*|verletzung|notfall|unfall|bewusstlos|ohnmächtig|herzinfarkt|blutet|blutung|lebensgefahr|notruf|gasgeruch|zusammengebrochen)', 'i');
const gefahr = gefahrWort.test(String(cfg.question ?? ''));
const ueberGrenze = bisher >= grenze;
const gefahrVorrang = ueberGrenze && gefahr && bisher < grenze + puffer;
const frageRest = String(cfg.question ?? '').replace(/[\s\p{Cf}\p{Cc}\p{Mn}ᅟᅠㅤﾠ឴឵⠀͏￼︀-️]/gu, '');
return [{ json: {
  nachrichten_bisher: bisher,
  erste_antwort: bisher === 0,
  limit_erreicht: ueberGrenze && !gefahrVorrang,
  gefahr_vorrang: gefahrVorrang,
  frage_vorhanden: frageRest.length > 0,
  grenze
} }];

// Baut den Zustand fuer Jev: Praefix, die letzten 3 Wechsel der Sitzung (bis zu 6 Nachrichten) und die aktuelle Nachricht.
// Jev speichert nichts selbst; der Verlauf kommt aus der Tabelle des Gespraechsgedaechtnisses.
// Testschalter h=0 (nur manuelle Laeufe) laesst den Verlauf weg, damit sich die Wirkung messen laesst.
const cfg = $('Konfiguration [Edit Fields]').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.message && Number(r.id ?? 0) > 0)
  .sort((a, b) => Number(a.id) - Number(b.id));
const msgs = rows.map(r => {
  let m = r.message;
  if (typeof m === 'string') { try { m = JSON.parse(m); } catch (e) { m = {}; } }
  return { typ: m.type, text: String(m.content ?? '') };
}).filter(m => (m.typ === 'human' || m.typ === 'ai') && m.text);
const letzte = msgs.slice(-6);
const mitVerlauf = cfg.jev_verlauf_an === true && letzte.length > 0;
const kurz = (t) => t.length > 400 ? t.slice(0, 400) + ' ...' : t;
let state = cfg.jev_state_prefix;
if (mitVerlauf) {
  state += 'Bisheriger Verlauf der Sitzung (älteste Nachricht zuerst):\n'
    + letzte.map(m => (m.typ === 'human' ? 'Person: ' : 'Assistent: ') + kurz(m.text)).join('\n')
    + '\n\nAktuelle Nachricht der Person: ' + cfg.question;
} else {
  state += cfg.question;
}
// v09: die letzte Antwort des Assistenten geht deterministisch an den Aktions-Sub (vorige_antwort), damit er ein Ja der Person gegen seine Rueckfrage pruefen kann.
const letzteAi = [...letzte].reverse().find(m => m.typ === 'ai');
return [{ json: { jev_state: state, verlauf_nachrichten: letzte.length, jev_mit_verlauf: mitVerlauf, vorige_antwort: letzteAi ? letzteAi.text.slice(0, 1500) : '' } }];

// Speichert den ausgegebenen Dialog der festen Wege (feste Rueckfrage, feste Fremdantwort) im Gespraechsgedaechtnis, damit Jev bei der naechsten Nachricht
// die Frage und den festen Text sieht (sonst fehlt ihm bei einer Kurzantwort wie "ja, genau das" der Kontext). Format wie beim Dauergedaechtnis des Agenten.
const cfg = $('Konfiguration [Edit Fields]').first().json;
const cur = $input.first().json;
const nachricht = (type, content) => ({ json: { session_id: cfg.session_id, message: { type, content, additional_kwargs: {}, response_metadata: {} } } });
return [nachricht('human', String(cfg.question ?? '')), nachricht('ai', String(cur.output ?? ''))];

// Adapter zwischen Orchestrator und Prüfknoten. Der Orchestrator ruft nur die Spezialisten Auskunfts_Agent und Aktions_Agent;
// die echten Werkzeugaufrufe stecken in deren Rückgabe (Feld werkzeuge). Der Adapter ersetzt intermediateSteps durch diese Schritte
// in der Form, die Werkzeugwahl messen seit v06 liest (action.tool, observation). Der Prüfknoten bekam in v08 nur die Zusage-Regel für "notiert" und Verwandte.
// agents_steps hält die Schritte des Orchestrators, agents_called nennt die gerufenen Spezialisten in Aufrufreihenfolge.
// v08, Belege bleiben: die Werkzeugschritte eines Spezialisten bleiben auch bei status error erhalten, damit eine bestätigte Teilaktion (Vormerkung steht, Rest gescheitert) nicht verloren geht.
// Dahinter steht der Fehlerschritt mit dem Spezialistennamen und einem Text mit "error": der Prüfknoten zählt ihn als Werkzeugfehler, und keine Zusage gilt als bestätigt, die ein Werkzeug nicht belegt (sichere Richtung).
// v08, fester Ausfallpfad: Fehlt die Antwort eines Spezialisten (nicht lesbar, status error, leere antwort) oder ist die Antwort des Orchestrators leer, ersetzt der Adapter sie durch den festen Ausfallsatz,
// es sei denn, eine Aktion ist belegt (Vormerkung mit Nummer oder Eilmeldung mit accepted): dann bleibt der Text des Orchestrators und der Prüfknoten sichert ihn ab. EINGABE_FEHLT ist kein Ausfall (der Orchestrator fragt nach).
// v09: Der Adapter liest aktion_stand des Spezialisten. Steht dort werkzeug_lief oder bestaetigt, verdeckt der feste Ausfallsatz das nicht: er bekommt den Zusatz, dass ein Teil des Vorgangs schon ausgefuehrt worden sein kann (keine Zusage, keine Nummer erfunden). Eine bestaetigte Teilaktion (Beleg in werkzeuge) bleibt wie in v08 im Text des Orchestrators.
