const item = $input.first().json;
const orch = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];
const SPEZ = ['Auskunfts_Agent', 'Aktions_Agent'];
const AUSFALL = 'Das hat gerade nicht geklappt. Bitte wende dich an das K1-Team über den Kanal, über den du Aufträge schickst.';
const TEIL = ' Ein Teil des Vorgangs kann schon ausgeführt worden sein.';
let teil = false;
const auspacken = (o) => {
  // Rückgabe als Text mit JSON, als Objekt oder als Liste (Form erst im Probelauf gemessen): bis zu 4 Ebenen auspacken.
  let v = o;
  for (let i = 0; i < 4; i++) {
    if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { return null; } }
    else if (Array.isArray(v)) { v = v[0]; }
    else if (v && typeof v === 'object' && v.status === undefined && v.json && typeof v.json === 'object') { v = v.json; }
    else if (v && typeof v === 'object' && v.status === undefined && typeof v.response === 'string') { v = v.response; }
