const txt = (o) => typeof o === 'string' ? o : JSON.stringify(o ?? '');
const steps = [];
const agents = [];
let ausfall = '';
for (const s of orch) {
  if (!s || !s.action || !s.action.tool) continue;
  const name = s.action.tool;
  agents.push(name);
  if (!SPEZ.includes(name)) { steps.push({ action: { tool: name }, observation: txt(s.observation) }); continue; }
  const r = auspacken(s.observation);
  if (!r) { steps.push({ action: { tool: name }, observation: 'error: Rückgabe des Spezialisten nicht lesbar' }); ausfall = ausfall || 'Rückgabe nicht lesbar'; continue; }
  const w = Array.isArray(r.werkzeuge) ? r.werkzeuge : [];
  for (const x of w) if (x && typeof x.tool === 'string' && x.tool) steps.push({ action: { tool: x.tool }, observation: txt(x.observation) });
  if (r.status !== 'ok') {
    steps.push({ action: { tool: name }, observation: 'error: ' + String(r.antwort || r.fehler_text || 'SPEZIALIST_AUSGEFALLEN').slice(0, 200) });
    if (!/^EINGABE_FEHLT/.test(String(r.antwort || ''))) { ausfall = ausfall || 'Spezialist meldet status error'; if (/^(werkzeug_lief|bestaetigt)$/.test(String(r.aktion_stand || ''))) { teil = true; ausfall += ' (aktion_stand ' + r.aktion_stand + ')'; } }
    continue;
  }
  if (!String(r.antwort ?? '').trim()) { steps.push({ action: { tool: name }, observation: 'error: leere Rückgabe des Spezialisten' }); ausfall = ausfall || 'leere Antwort'; }
}
// Beleg einer Aktion: Vormerkung mit Nummer oder Eilmeldung mit angenommenem Empfänger (lockere Sicht, der Prüfknoten liest streng).
const belegt = steps.some(x => (x.action.tool === 'Teamvormerkung' && /erfasst/.test(x.observation) && /K1-T-\d{5}/.test(x.observation)) || (x.action.tool === 'Eilmeldung_ans_Team' && /accepted/.test(x.observation) && !/rejected[\\"]+\s*:\s*\[\s*[\\"]+/.test(x.observation)));
const KI = 'Du schreibst mit dem KI-Assistenten von K1.';
const leer = !String(item.output ?? '').replace(KI, '').trim();
let output = item.output;
let sach = false;
if (!ausfall && !leer && agents.length === 0) {
  let kontext = '';
  try { kontext = String($('Jev-Zustand bauen [Code]').first().json.jev_state ?? ''); } catch (e) { kontext = ''; }
  try { kontext += ' ' + String($('Konfiguration [Edit Fields]').first().json.question ?? ''); } catch (e) { /* ohne Kontext zaehlt jede Zahl als neu */ }
  const zahlen = String(item.output).match(/(?<![A-Za-zÄÖÜäöüß])\d[\d.,:]*\d|(?<![A-Za-zÄÖÜäöüß])\d(?![A-Za-zÄÖÜäöüß\d])/g) || [];
  const neueZahl = zahlen.some(z => !kontext.includes(z));
  const sachwort = /(kostet|kosten\s+\d|beträgt|dauert|innerhalb von|Stunden|Werktage|Euro|€|Prozent|%|Garantie|Lieferzeit)/i.test(String(item.output));
  sach = !/\?/.test(String(item.output)) && (neueZahl || sachwort);
}
if ((ausfall || leer || sach) && !belegt) {
  output = AUSFALL + (teil ? TEIL : '');
  steps.push({ action: { tool: 'Ausfallpfad' }, observation: 'error: ' + (ausfall || (sach ? 'Sachaussage ohne Spezialist' : 'keine Antwort des Orchestrators')) });
}
