  // v12: ALLE bestaetigten Aktionen werden gesammelt (jede Ticketnummer, die Mail) und gemeinsam genannt.
  // Bei Ausfall wird der Text des Orchestrators immer ersetzt (v11). Im Erfolgsweg (status ok) bleibt der Text des Modells unveraendert, auch wenn er einer Aktion widerspricht (v14): der feste Absatz im Pruefknoten traegt den Stand aus den Belegen.
  const REST = ' Der Rest des Vorgangs hat nicht geklappt, bitte wende dich an das K1-Team über den Kanal, über den du Aufträge schickst.';
  const outS0 = String(output ?? '');
  const kiHinweis = outS0.startsWith('Du schreibst mit dem KI-Assistenten von K1.') ? 'Du schreibst mit dem KI-Assistenten von K1. ' : '';
  const nummern = [];
  for (const x of steps) if (x.action.tool === 'Teamvormerkung' && /erfasst/.test(x.observation)) { const n = (x.observation.match(/K1-T-\d{5}/) || [])[0]; if (n && !nummern.includes(n)) nummern.push(n); }
  const mailBeleg = steps.some(x => x.action.tool === 'Eilmeldung_ans_Team' && /accepted/.test(x.observation) && !/rejected[\\"]+\s*:\s*\[\s*[\\"]+/.test(x.observation));
  const satzTicket = (verb) => nummern.length === 0 ? '' : (nummern.length === 1 ? 'Die Vormerkung ' + nummern[0] + ' ' + verb[0] : 'Die Vormerkungen ' + nummern.slice(0, -1).join(', ') + ' und ' + nummern[nummern.length - 1] + ' ' + verb[1]);
  const belegSaetze = (verb) => [nummern.length ? satzTicket(verb) + '.' : '', mailBeleg ? 'Das K1-Team wurde informiert.' : ''].filter(Boolean).join(' ');
  if (ausfall) {
    output = kiHinweis + belegSaetze(['steht bereits', 'stehen bereits']) + REST;
  } else if (leer) {
    output = kiHinweis + AUSFALL;
  }
}
return [{ json: { ...item, output, intermediateSteps: steps, agents_steps: orch, agents_called: agents.join(',') } }];

// Ausgangs-Guardrail (V7, v13): prueft NUR den Modelltext der Antwort, je Muster ein eigener Regex, nie ein Sammeltext.
// Grundsatz: lieber zu wenig als zu viel ersetzen. Jedes Muster hat einen Koeder und einen harmlosen Gegenfall in der Testtabelle.
// Der Absatz "Bestaetigt: ..." stammt aus den Belegen des Pruefknotens (nicht aus dem Modell). Er wird nur dann vom Modelltext getrennt, wenn er genau dem
// Format des Pruefknotens entspricht (bekannte Bausteine); alles andere bleibt im Modelltext und wird mitgeprueft. Spaeter haengt Antwort zusammensetzen ihn wieder an.
// Getrennt wird nur, wenn dieser Lauf wirklich eine Aktion gerufen hat (tools_called).
// v12 (Gegenproben): Passwort- und Anweisungsmuster enger gefasst. 'Passwort lautet' nur, wenn der Wert am Satzende steht; 'Passwort ist' nur bei Werten mit Ziffer oder Sonderzeichen im Wort und ohne Bindestrich; 'Anweisungen lauten' nur als 'meine (System-)Anweisung' oder 'die Systemanweisung'.
// v13 (zweiter Gegentest): Satzzeichen am Satzende gehoeren nicht zum Passwortwert ('!' zaehlt nur mitten im Wort als Sonderzeichen); 'Passwort: Wert' trifft nicht, wenn der Wert ein Bedienverb ist (Bestaetigen, Wiederholen, Eingeben ...).
