}
return [{ json: { ...item, output: text, aktionsabsatz: absatz, guardrail_treffer: treffer, guardrail_hit: treffer !== '' } }];

// v11: setzt Modelltext (oder Ersatztext) und den Absatz "Bestaetigt: ..." zu der Antwort zusammen. Beide Zweige von Treffer? laufen hier hinein,
// damit bestaetigte Aktionen immer sichtbar bleiben, auch wenn der Modelltext ersetzt wurde.
const item = $input.first().json;
const text = String(item.output ?? '');
const absatz = String(item.aktionsabsatz ?? '');
const output = absatz ? (text ? text + '\n\n' + absatz : absatz) : text;
return [{ json: { ...item, output } }];
